from functools import reduce

def lcm(a,b): return a*b//gcd(a,b)

def factorize(n):
    d={}
    x=n
    p=2
    while p*p<=x:
        while x%p==0:
            d[p]=d.get(p,0)+1
            x//=p
        p+=1
    if x>1:
        d[x]=d.get(x,0)+1
    return d

def apply_move(board, i, j):
    m,n = board[i], board[j]
    g = gcd(m,n)
    l = lcm(m,n)//g
    board[i], board[j] = g, l
    return board

def simulate(board):
    board = board[:]
    steps=0
    while sum(1 for x in board if x>1) >= 2:
        idxs = [i for i,x in enumerate(board) if x>1]
        i,j = random.sample(idxs,2)
        apply_move(board,i,j)
        steps+=1
    return max(board)

def predicted_M(board):
    allfact = [factorize(x) for x in board]
    primes = set()
    for f in allfact: primes |= set(f.keys())
    M = 1
    for p in primes:
        vals = [f.get(p,0) for f in allfact]
        g = reduce(gcd, vals)
        M *= p**g
    return M

